;
;
;       NAME:           GetSin
;
;       DESCRIPTION:    Get sin value from 18-bit phase
;
;       PARAMETERS:     Phase
;
;       RETURNS:        Value
;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

    public _GetSin

_GetSin  Proc near
    mov eax,[esp+4]
    and eax,3FFFFh
    movsx eax,word ptr [2*eax].sin_tab
    ret 4
_GetSin    Endp

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;
;
;       NAME:           GetSin32
;
;       DESCRIPTION:    Get sin value from 32-bit phase
;
;       PARAMETERS:     Phase
;
;       RETURNS:        Value
;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

    public _GetSin32

_GetSin32  Proc near
    mov eax,[esp+4]
    push ebx
    push ecx
    push edx
;
    movzx ecx,ax
    and cx,3FFFh
;
    shr eax,13
    and al,0FEh
    mov ebx,eax
;
    movsx eax,word ptr [ebx].sin_tab+2
    imul ecx
;
    mov edx,4000h
    sub edx,ecx
    mov ecx,eax
;
    movsx eax,word ptr [ebx].sin_tab
    imul edx
;
    add eax,ecx
    shr eax,14
;
    pop edx
    pop ecx
    pop ebx
    ret 4
_GetSin32    Endp

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;
;
;       NAME:           CalcFreqPower
;
;       DESCRIPTION:    Calc power at a given frequency
;
;       PARAMETERS:     Data
;                       Size
;                       RelFreq
;                       Res
;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

    public _CalcFreqPower

_CalcFreqPower  Proc near
    pushad
;
    mov esi,[esp+24h]
    mov ecx,[esp+28h]
    mov edi,[esp+30h]
    xor ebx,ebx
    mov ebp,10000h
;
    xor eax,eax
    mov [edi].sin_a,eax
    mov [edi].sin_a+4,eax
    mov [edi].sin_b,eax
    mov [edi].sin_b+4,eax
    mov [edi].cos_a,eax
    mov [edi].cos_a+4,eax
    mov [edi].cos_b,eax
    mov [edi].cos_b+4,eax

cfpLoop:
    mov ax,[2*ebx].sin_tab
    imul word ptr [esi]
    movsx edx,dx
    add word ptr [edi].sin_a,ax
    adc dword ptr [edi].sin_a+2,edx
;
    mov ax,ds:[2*ebp].sin_tab
    imul word ptr [esi]
    movsx edx,dx
    add word ptr [edi].cos_a,ax
    adc dword ptr [edi].cos_a+2,edx
    add esi,2
;
    mov ax,[2*ebx].sin_tab
    imul word ptr [esi]
    movsx edx,dx
    add word ptr [edi].sin_b,ax
    adc dword ptr [edi].sin_b+2,edx
;
    mov ax,ds:[2*ebp].sin_tab
    imul word ptr [esi]
    movsx edx,dx
    add word ptr [edi].cos_b,ax
    adc dword ptr [edi].cos_b+2,edx
    add esi,2
;
    add ebx,[esp+2Ch]
    and ebx,3FFFFh
;
    add ebp,[esp+2Ch]
    and ebp,3FFFFh
;
    loop cfpLoop
;
    movsx eax,word ptr [edi].sin_a+4
    mov [edi].sin_a+4,eax
;
    movsx eax,word ptr [edi].sin_b+4
    mov [edi].sin_b+4,eax
;
    movsx eax,word ptr [edi].cos_a+4
    mov [edi].cos_a+4,eax
;
    movsx eax,word ptr [edi].cos_b+4
    mov [edi].cos_b+4,eax
;
    popad
    ret 16
_CalcFreqPower    Endp

;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;
;
;
;       NAME:           CalcPower
;
;       DESCRIPTION:    Calc signal power
;
;       PARAMETERS:     Data
;                       Size
;                       Res
;
;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;

    public _CalcPower

_CalcPower  Proc near
    pushad
;
    mov esi,[esp+24h]
    mov ecx,[esp+28h]
    mov edi,[esp+2Ch]
;
    xor eax,eax
    mov [edi].pow_a,eax
    mov [edi].pow_a+4,eax
    mov [edi].pow_b,eax
    mov [edi].pow_b+4,eax

cpLoop:
    mov ax,[esi]
    imul ax
    movsx edx,dx
    add word ptr [edi].pow_a,ax
    adc dword ptr [edi].pow_a+2,edx
    add esi,2
;
    mov ax,[esi]
    imul ax
    movsx edx,dx
    add word ptr [edi].pow_b,ax
    adc dword ptr [edi].pow_b+2,edx
    add esi,2
;
    loop cpLoop
;
    popad
    ret 12
_CalcPower    Endp

  END
